package io.tenvyr.worker;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.sun.net.httpserver.HttpServer;
import io.tenvyr.platform.Json;
import java.io.*;
import java.net.*;
import java.net.http.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.time.Duration;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;

/** Real HTTP adversarial, callback and scheduling stress checks. Requires loopback binding. */
public final class WorkerIntegrationCheck {
    private static final HttpClient CLIENT=HttpClient.newBuilder().followRedirects(HttpClient.Redirect.NEVER).build();
    private static ObjectNode template;private static int callbackPort;
    private static final List<Captured> captured=new CopyOnWriteArrayList<>();private static final AtomicInteger callbackStatus=new AtomicInteger(200),callbackBytes=new AtomicInteger(),callbackAttempts=new AtomicInteger();private static volatile int retryResponses;
    record Captured(byte[] raw,String id,String timestamp,String signature,JsonNode body){}
    static void check(boolean value,String message){if(!value)throw new AssertionError(message);}
    static WorkerConfig config(){WorkerConfig c=new WorkerConfig();c.agentName="echo-agent";c.bearerToken="token";c.callbackKeys=Map.of("key","secret");c.allowedOrigins=List.of("http://127.0.0.1:"+callbackPort);c.allowInsecureHttp=true;c.callbackMaxAttempts=3;c.callbackInitialDelayMs=20;c.callbackMaxDelayMs=100;c.callbackJitterRatio=0;c.callbackRequestTimeoutMs=1000;c.shutdownGraceMs=1000;return c;}
    static ObjectNode request(String id){ObjectNode request=template.deepCopy(),invocation=(ObjectNode)request.get("invocation");invocation.put("invocationId",id).put("stepExecutionId","step-"+id);request.set("resultDelivery",Json.object("mode","callback","callbackUrl","http://127.0.0.1:"+callbackPort+"/callback","authentication",Json.object("scheme","hmac-sha256","keyId","key")));return request;}
    static HttpResponse<String> submit(Worker worker,ObjectNode request)throws Exception{return submit(worker,Json.stringify(request),request.path("invocation").path("invocationId").asText(),"token");}
    static HttpResponse<String> submit(Worker worker,String raw,String id,String token)throws Exception{return CLIENT.send(HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+worker.port()+"/v1/runs")).timeout(Duration.ofSeconds(3)).header("Content-Type","application/json").header("Authorization","Bearer "+token).header("Idempotency-Key",id).POST(HttpRequest.BodyPublishers.ofString(raw)).build(),HttpResponse.BodyHandlers.ofString());}
    static void await(java.util.function.BooleanSupplier condition,String message)throws Exception{long deadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(5);while(!condition.getAsBoolean()&&System.nanoTime()<deadline)Thread.sleep(10);check(condition.getAsBoolean(),message);}
    static long results(String id){return captured.stream().filter(c->c.body.has("status")&&id.equals(c.body.path("invocationId").asText())).count();}
    static JsonNode result(String id){return captured.stream().filter(c->c.body.has("status")&&id.equals(c.body.path("invocationId").asText())).findFirst().orElseThrow().body;}
    public static void main(String[] args)throws Exception {
        Path root=Path.of(args.length>0?args[0]:".");template=(ObjectNode)Json.parse(Files.readString(root.resolve("contracts/conformance/run-request/valid/minimal.json")));
        HttpServer callback=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);ExecutorService executor=Executors.newCachedThreadPool();callback.setExecutor(executor);callback.createContext("/",exchange->{byte[] raw=exchange.getRequestBody().readAllBytes();String id=exchange.getRequestHeaders().getFirst(CallbackDelivery.DELIVERY_ID),timestamp=exchange.getRequestHeaders().getFirst(CallbackDelivery.TIMESTAMP),signature=exchange.getRequestHeaders().getFirst(CallbackDelivery.SIGNATURE);check("key".equals(exchange.getRequestHeaders().getFirst(CallbackDelivery.KEY_ID)),"Callback key header");check(CallbackDelivery.signature("secret",timestamp,id,raw).equals(signature),"Signature over exact transmitted bytes");captured.add(new Captured(raw,id,timestamp,signature,Json.parse(new String(raw,StandardCharsets.UTF_8))));int attempt=callbackAttempts.incrementAndGet();int status=attempt<=retryResponses?503:callbackStatus.get();if(attempt<=retryResponses)exchange.getResponseHeaders().set("Retry-After","0");byte[] response=new byte[callbackBytes.get()];exchange.sendResponseHeaders(status,response.length==0?-1:response.length);if(response.length>0)exchange.getResponseBody().write(response);exchange.close();});callback.start();callbackPort=callback.getAddress().getPort();
        try{admissionAndFifo();callbackChecks();eventsAndTimeout();stress();shutdownChecks();System.out.println("Worker HTTP/adversarial/stress integration checks passed");}finally{callback.stop(0);executor.shutdownNow();}
    }
    static void admissionAndFifo()throws Exception {
        CountDownLatch firstStarted=new CountDownLatch(1),release=new CountDownLatch(1);List<String> order=new CopyOnWriteArrayList<>();WorkerConfig c=config();c.concurrency=1;c.maxQueuedRuns=1;c.idempotencyMaxEntries=2;
        try(Worker worker=new Worker(c,(ctx,input)->{order.add(ctx.invocation.path("invocationId").asText());firstStarted.countDown();release.await();return Json.object("output","raw");})){
            worker.start("127.0.0.1",0);check(worker.start("127.0.0.1",0).getPort()==worker.port(),"Idempotent start");check(CLIENT.send(HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+worker.port()+"/health/ready")).GET().build(),HttpResponse.BodyHandlers.ofString()).statusCode()==200,"Ready health");
            check(submit(worker,"invalid json","auth","bad").statusCode()==401,"Bearer before JSON parsing");HttpResponse<String> accepted=submit(worker,request("fifo-a"));check(accepted.statusCode()==202&&firstStarted.await(1,TimeUnit.SECONDS),"Async 202 before completion");check(results("fifo-a")==0,"No early result");check(submit(worker,request("fifo-b")).statusCode()==202,"Queue admission");check(submit(worker,request("fifo-c")).statusCode()==429,"Running plus queue capacity bounded");
            check(submit(worker,request("fifo-a")).body().equals(accepted.body()),"Duplicate before capacity preserves acceptance");ObjectNode conflict=request("fifo-a");((ObjectNode)conflict.get("invocation")).set("input",Json.object("changed",true));check(submit(worker,conflict).statusCode()==409,"Conflicting invocation refused");
            release.countDown();await(()->results("fifo-a")==1&&results("fifo-b")==1,"One terminal result per FIFO run");check(order.equals(List.of("fifo-a","fifo-b")),"FIFO handler order");check(result("fifo-a").path("output").path("output").asText().equals("raw"),"Direct object output is raw");
        }finally{release.countDown();}
        WorkerConfig small=config();small.maxRequestBytes=100;try(Worker worker=new Worker(small,(ctx,input)->input)){worker.start("127.0.0.1",0);check(submit(worker,request("oversize")).statusCode()==413,"Request byte bound");}
        try(Worker worker=new Worker(config(),(ctx,input)->input)){worker.start("127.0.0.1",0);ObjectNode unsafe=request("unsafe");String raw=Json.stringify(unsafe).replace("\"input\":null","\"input\":9007199254740992");check(submit(worker,raw,"unsafe","token").statusCode()==400,"Unsafe inbound bytes rejected");check(submit(worker,unsafe).statusCode()==202,"Rejected inbound request leaves no phantom idempotency record");await(()->results("unsafe")==1,"Valid retry executes");ObjectNode bad=request("bad-origin");((ObjectNode)bad.get("resultDelivery")).put("callbackUrl","http://127.0.0.1:"+callbackPort+"/path?secret=1");check(submit(worker,bad).statusCode()==400,"Callback URL query refused");}
        // The unauthenticated client never sends its declared body. Authentication must still answer.
        try(Worker worker=new Worker(config(),(ctx,input)->input)){worker.start("127.0.0.1",0);try(Socket socket=new Socket("127.0.0.1",worker.port())){socket.setSoTimeout(1000);socket.getOutputStream().write(("POST /v1/runs HTTP/1.1\r\nHost: localhost\r\nContent-Type: application/json\r\nAuthorization: Bearer bad\r\nContent-Length: 999999\r\n\r\n").getBytes(StandardCharsets.US_ASCII));check(new BufferedReader(new InputStreamReader(socket.getInputStream())).readLine().contains("401"),"Bearer-before-body processing");}}
    }
    static void callbackChecks()throws Exception {
        callbackAttempts.set(0);retryResponses=2;captured.clear();try(Worker worker=new Worker(config(),(ctx,input)->Json.object("unicode","Xin chào 🌏","__proto__",true))){worker.start("127.0.0.1",0);check(submit(worker,request("retry")).statusCode()==202,"Callback retry admitted");await(()->results("retry")==3,"Transient retries bounded");List<Captured> deliveries=captured.stream().filter(c->c.body.has("status")).toList();check(deliveries.stream().map(Captured::id).distinct().count()==1,"Stable retry delivery ID");check(deliveries.stream().allMatch(c->Arrays.equals(c.raw,deliveries.get(0).raw)),"Serialized-once retry bytes");check(submit(worker,request("retry")).statusCode()==202,"Delivered duplicate accepted");Thread.sleep(100);check(results("retry")==3,"No duplicate callback execution");}retryResponses=0;
        for(int status:List.of(400,302)){callbackStatus.set(status);callbackAttempts.set(0);AtomicInteger hook=new AtomicInteger();WorkerConfig c=config();c.onCallbackDeliveryFailed=outcome->{hook.incrementAndGet();throw new RuntimeException("hook failure");};String id="permanent-"+status;try(Worker worker=new Worker(c,(ctx,input)->Json.object())){worker.start("127.0.0.1",0);submit(worker,request(id));await(()->hook.get()==1,"Permanent failure hook exactly once");check(results(id)==1,"Permanent status does not retry/follow redirect");}}callbackStatus.set(200);
        callbackBytes.set(1024);WorkerConfig c=config();c.maxResponseBytes=100;AtomicInteger hook=new AtomicInteger();c.onCallbackDeliveryFailed=outcome->{check(outcome.reason().equals("response-too-large"),"Oversized callback response classification");hook.incrementAndGet();};try(Worker worker=new Worker(c,(ctx,input)->Json.object())){worker.start("127.0.0.1",0);submit(worker,request("large-response"));await(()->hook.get()==1,"Declared oversized response rejected");check(results("large-response")==1,"Oversized response does not retry");}callbackBytes.set(0);
    }
    static void eventsAndTimeout()throws Exception {
        WorkerConfig c=config();c.eventsEnabled=true;c.heartbeatIntervalMs=1000;try(Worker worker=new Worker(c,(ctx,input)->{ctx.progress(Json.object("percent",20));ctx.log("safe log");ctx.artifact(Json.object("uri","urn:test:artifact"));return ctx.success(Json.object("done",true));})){worker.start("127.0.0.1",0);submit(worker,request("events"));await(()->captured.stream().filter(x->"events".equals(x.body.path("invocationId").asText())).count()==6,"Result plus accepted/progress/log/artifact/completed events");List<JsonNode> events=captured.stream().map(Captured::body).filter(x->x.has("eventId")&&"events".equals(x.path("invocationId").asText())).sorted(Comparator.comparingLong(x->x.path("sequence").asLong())).toList();check(events.size()==5&&events.get(0).path("type").asText().equals("accepted")&&events.get(4).path("type").asText().equals("completed"),"System event envelope");for(int i=0;i<events.size();i++)check(events.get(i).path("eventId").asText().equals("events:"+i),"Independent monotonic event identity");}
        WorkerConfig timeout=config();timeout.timeoutMs=50;AtomicBoolean cancelled=new AtomicBoolean();CompletableFuture<JsonNode> late=new CompletableFuture<>();try(Worker worker=new Worker(timeout,(ctx,input)->{ctx.signal.onCancel(()->cancelled.set(true));return late;})){worker.start("127.0.0.1",0);submit(worker,request("timeout"));await(()->results("timeout")==1,"Timeout result callback");check(cancelled.get()&&result("timeout").path("status").asText().equals("timed_out"),"Cooperative timeout classification");late.complete(Json.object("tooLate",true));Thread.sleep(100);check(results("timeout")==1,"Late completion does not deliver a second result");}
    }
    static void stress()throws Exception {
        AtomicInteger running=new AtomicInteger(),max=new AtomicInteger(),executed=new AtomicInteger();WorkerConfig c=config();c.concurrency=4;c.maxQueuedRuns=100;c.idempotencyMaxEntries=200;
        try(Worker worker=new Worker(c,(ctx,input)->{int now=running.incrementAndGet();max.accumulateAndGet(now,Math::max);try{Thread.sleep(20);executed.incrementAndGet();return Json.object("ok",true);}finally{running.decrementAndGet();}})){worker.start("127.0.0.1",0);for(int i=0;i<100;i++){ObjectNode request=request("stress-"+i);check(submit(worker,request).statusCode()==202,"Stress admission "+i);if(i%5==0)check(submit(worker,request).statusCode()==202,"Stress duplicate "+i);}await(()->captured.stream().filter(x->x.body.has("status")&&x.body.path("invocationId").asText().startsWith("stress-")).count()==100,"100 signed stress callbacks");check(executed.get()==100&&max.get()<=4,"Bounded concurrency and one execution per invocation");}
    }
    static void shutdownChecks()throws Exception {
        CountDownLatch began=new CountDownLatch(1);AtomicBoolean cancelled=new AtomicBoolean();WorkerConfig c=config();c.concurrency=1;c.maxQueuedRuns=1;Worker worker=new Worker(c,(ctx,input)->{began.countDown();ctx.signal.onCancel(()->cancelled.set(true));return new CompletableFuture<>();});worker.start("127.0.0.1",0);submit(worker,request("shutdown-active"));check(began.await(1,TimeUnit.SECONDS),"Active shutdown fixture");submit(worker,request("shutdown-queued"));CompletableFuture<Void> stop=worker.stop(100);check(CLIENT.send(HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+worker.port()+"/health/ready")).GET().build(),HttpResponse.BodyHandlers.ofString()).statusCode()==503,"Readiness off during shutdown");check(submit(worker,request("shutdown-new")).statusCode()==503,"Stopping refuses new work");stop.get(3,TimeUnit.SECONDS);check(cancelled.get()&&worker.state().equals("stopped"),"Shutdown grace expires and execution ownership settles");check(worker.stop()==stop,"Concurrent stop returns same settled future");
        callbackStatus.set(503);WorkerConfig retries=config();retries.callbackMaxAttempts=100;retries.callbackInitialDelayMs=1000;retries.callbackMaxDelayMs=1000;Worker retrying=new Worker(retries,(ctx,input)->Json.object());retrying.start("127.0.0.1",0);submit(retrying,request("shutdown-backoff"));await(()->results("shutdown-backoff")>=1,"Retry backoff started");retrying.stop(20).get(2,TimeUnit.SECONDS);check(retrying.state().equals("stopped"),"Stop waits for aborted callback retry sleep");callbackStatus.set(200);
        try(Worker partial=new Worker(config(),(ctx,input)->input)){partial.start("127.0.0.1",0);try(Socket socket=new Socket("127.0.0.1",partial.port())){socket.setSoTimeout(1000);socket.getOutputStream().write(("POST /v1/runs HTTP/1.1\r\nHost: localhost\r\nContent-Type: application/json\r\nAuthorization: Bearer token\r\nContent-Length: 9999\r\n\r\nx").getBytes(StandardCharsets.US_ASCII));partial.stop(20).get(2,TimeUnit.SECONDS);check(socket.getInputStream().read()==-1,"Incomplete authenticated request closed on stop");}}
    }
}
